param([string]$Workspace,[string]$Procedure)
$ErrorActionPreference='Stop';Add-Type -AssemblyName UIAutomationClient;Add-Type -AssemblyName UIAutomationTypes
$c=Get-Content (Join-Path $Workspace 'wfe-run.json') -Raw|ConvertFrom-Json;$steps=(Get-Content $Procedure -Raw|ConvertFrom-Json).steps;$evidence=@()
function StartApp{$cmd=Join-Path $Workspace $c.start.command;$sp=@{FilePath=$cmd;WorkingDirectory=$Workspace;PassThru=$true};if($c.start.args -and $c.start.args.Count){$sp.ArgumentList=$c.start.args};$script:p=Start-Process @sp;for($i=0;$i-lt 100;$i++){Start-Sleep -Milliseconds 100;$r=[System.Windows.Automation.AutomationElement]::RootElement;$q=New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::ProcessIdProperty,$script:p.Id);$script:w=$r.FindFirst([System.Windows.Automation.TreeScope]::Children,$q);if($script:w){$script:evidence+=@([pscustomobject]@{op='ready';pass=$true;pid=$script:p.Id;window=$script:w.Current.Name});return}};throw 'process-window readiness timeout'}
function Elem($id){$q=New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::AutomationIdProperty,$id);$x=$script:w.FindFirst([System.Windows.Automation.TreeScope]::Descendants,$q);if(!$x){throw "element missing: $id"};$x}
function VP($x){try{return $x.GetCurrentPattern([System.Windows.Automation.ValuePattern]::Pattern)}catch{$q=New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::IsValuePatternAvailableProperty,$true);$y=$x.FindFirst([System.Windows.Automation.TreeScope]::Descendants,$q);if(!$y){throw 'ValuePattern unavailable'};return $y.GetCurrentPattern([System.Windows.Automation.ValuePattern]::Pattern)}}
function StopApp{$id=$script:p.Id;Stop-Process -Id $id -Force;$script:p.WaitForExit();$dead= -not [bool](Get-Process -Id $id -ErrorAction SilentlyContinue);$script:evidence+=@([pscustomobject]@{op='stopped';pass=$dead;pid=$id});if(!$dead){throw 'process did not stop'}}
try{StartApp;foreach($s in $steps){if($s.op -eq 'setValue'){(VP (Elem $s.id)).SetValue([string]$s.value);$evidence+=@([pscustomobject]@{op=$s.op;id=$s.id;pass=$true;value=[string]$s.value})}elseif($s.op -eq 'invoke'){try{(Elem $s.id).GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern).Invoke()}catch{};Start-Sleep -Milliseconds 300;$evidence+=@([pscustomobject]@{op=$s.op;id=$s.id;pass=$true})}elseif($s.op -eq 'assertValue'){$v=(VP (Elem $s.id)).Current.Value;$pass=$v.Contains([string]$s.contains);$evidence+=@([pscustomobject]@{op=$s.op;id=$s.id;pass=$pass;observed=$v});if(!$pass){throw "assertValue failed $($s.id): $v"}}elseif($s.op -eq 'assertGridValues'){$g=Elem $s.id;$q=New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::ControlTypeProperty,[System.Windows.Automation.ControlType]::DataItem);$cells=$g.FindAll([System.Windows.Automation.TreeScope]::Descendants,$q);$vals=@();foreach($x in $cells){try{$vals+=(VP $x).Current.Value}catch{}};$miss=@($s.values|?{$vals -notcontains [string]$_});$pass=$miss.Count -eq 0;$evidence+=@([pscustomobject]@{op=$s.op;id=$s.id;pass=$pass;observed=$vals});if(!$pass){throw "grid values missing: $($miss -join ',')"}}elseif($s.op -eq 'restart'){StopApp;StartApp}else{throw "unsupported op $($s.op)"}};StopApp;[pscustomobject]@{pass=$true;evidence=$evidence}|ConvertTo-Json -Depth 6 -Compress}catch{try{if($p -and -not $p.HasExited){StopApp}}catch{};[pscustomobject]@{pass=$false;error=$_.Exception.Message;evidence=$evidence}|ConvertTo-Json -Depth 6 -Compress;exit 1}